#[allow(unused_imports)]
use lushtext_core::services::draft_service::journal_core::RestoreEnding;
use lushtext_journal_stateright::env::{Action, Journal, PreviousId};

#[test]
fn tlc_k8_6_body_without_entry() {
    let previous = [
        PreviousId { entry: true, body: false, backing_moved: false },
        PreviousId { entry: true, body: false, backing_moved: false },
        PreviousId { entry: true, body: false, backing_moved: false },
    ];
    let mut journal = Journal::previous_session(previous).with_second_process();
    journal.step_as(false, Action::Startup, 0, false, None);
    journal.step_as(true, Action::Startup, 0, false, None);
    journal.step_as(false, Action::Edit, 0, false, None);
    journal.step_as(false, Action::Register, 0, false, None);
    journal.step_as(true, Action::Save, 0, false, None);
    journal.step_as(true, Action::DeletionStep, 0, false, None);
    journal.step_as(true, Action::DeletionStep, 0, false, None);
    journal.step_as(false, Action::WriteBody, 0, false, None);
    assert!(journal.body_without_entry, "the TLC counterexample reproduces on the real journal_core");
}
